---
import type { HTMLAttributes } from "astro/types"

type Props = HTMLAttributes<"div"> & {
  defaultOpen?: boolean
  closeOnClickOutside?: boolean
  closeOnEscape?: boolean
  lockScroll?: boolean
  alertDialog?: boolean
}

const {
  class: className,
  defaultOpen,
  closeOnClickOutside,
  closeOnEscape,
  lockScroll,
  alertDialog,
  ...props
} = Astro.props
---

<div
  data-slot="dialog"
  data-default-open={defaultOpen}
  data-close-on-click-outside={closeOnClickOutside}
  data-close-on-escape={closeOnEscape}
  data-lock-scroll={lockScroll}
  data-alert-dialog={alertDialog}
  class={className}
  {...props}
>
  <slot />
</div>

<script>
  import { create } from "@data-slot/dialog"

  const controllers: ReturnType<typeof create> = []
  const initialize = () => controllers.push(...create())
  initialize()
  document.addEventListener("astro:page-load", initialize)
  document.addEventListener("astro:before-swap", () => {
    for (const controller of controllers) controller.destroy()
    controllers.length = 0
  })
</script>

---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

import DialogClose from "./dialog-close.astro"

type Props = HTMLAttributes<"div"> & {
  showCloseButton?: boolean
}

const { class: className, showCloseButton = false, ...props } = Astro.props
---

<div
  data-slot="dialog-footer"
  class={cn(
    "bg-muted/50 -mx-4 -mb-4 rounded-b-xl border-t p-4 flex flex-col-reverse sm:flex-row sm:justify-end",
    className
  )}
  {...props}
>
  <slot />
  {showCloseButton && <DialogClose variant="outline">Close</DialogClose>}
</div>
